import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_28_alphastar_overview.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_28_state_modalities.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_28_memory_fusion.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_28_action_autoregressive.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_28_driving_boundary.png",f=JSON.parse('{"title":"AlphaStar 拆解篇一：复杂游戏如何表示状态与组合动作","description":"AlphaStar 的难点不只是策略网络大，而是环境本身包含多种数据类型、部分可观测视角、数量变化的单位实体和组合动作。StarCraft II（星际争霸 II）中，智能体要同时理解小地图、资源、建筑、兵种、历史信息和对手状态，还要按顺序选择动作类型、延迟、队列、单位和目标位置。把所有信息压成一个固","frontmatter":{"title":"AlphaStar 拆解篇一：复杂游戏如何表示状态与组合动作","description":"AlphaStar 的难点不只是策略网络大，而是环境本身包含多种数据类型、部分可观测视角、数量变化的单位实体和组合动作。StarCraft II（星际争霸 II）中，智能体要同时理解小地图、资源、建筑、兵种、历史信息和对手状态，还要按顺序选择动作类型、延迟、队列、单位和目标位置。把所有信息压成一个固","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":8,"source":"2026-08-13/rl_series_28_alphastar_representation_actions.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_28_alphastar_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-28-alphastar-representation-actions"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"AlphaStar 拆解篇一：复杂游戏如何表示状态与组合动作"}],["meta",{"property":"og:description","content":"AlphaStar 的难点不只是策略网络大，而是环境本身包含多种数据类型、部分可观测视角、数量变化的单位实体和组合动作。StarCraft II（星际争霸 II）中，智能体要同时理解小地图、资源、建筑、兵种、历史信息和对手状态，还要按顺序选择动作类型、延迟、队列、单位和目标位置。把所有信息压成一个固"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-28-alphastar-representation-actions"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_28_alphastar_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"AlphaStar 拆解篇一：复杂游戏如何表示状态与组合动作"}],["meta",{"name":"twitter:description","content":"AlphaStar 的难点不只是策略网络大，而是环境本身包含多种数据类型、部分可观测视角、数量变化的单位实体和组合动作。StarCraft II（星际争霸 II）中，智能体要同时理解小地图、资源、建筑、兵种、历史信息和对手状态，还要按顺序选择动作类型、延迟、队列、单位和目标位置。把所有信息压成一个固"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_28_alphastar_overview.png"}]],"prev":{"text":"专家到底在追求什么？从逆强化学习到 GAIL","link":"/rl/rl-series-27-irl-gail"},"next":{"text":"AlphaStar 拆解篇二：监督预训练、自博弈与联盟训练如何合成","link":"/rl/rl-series-29-alphastar-training-league"}},"headers":[],"relativePath":"rl/rl-series-28-alphastar-representation-actions.md","filePath":"rl/rl-series-28-alphastar-representation-actions.md","lastUpdated":null}'),p={name:"rl/rl-series-28-alphastar-representation-actions.md"};function d(c,a,_,u,b,m){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="alphastar-拆解篇一-复杂游戏如何表示状态与组合动作" tabindex="-1">AlphaStar 拆解篇一：复杂游戏如何表示状态与组合动作 <a class="header-anchor" href="#alphastar-拆解篇一-复杂游戏如何表示状态与组合动作" aria-label="Permalink to &quot;AlphaStar 拆解篇一：复杂游戏如何表示状态与组合动作&quot;">​</a></h1><p>AlphaStar 的难点不只是策略网络大，而是环境本身包含多种数据类型、部分可观测视角、数量变化的单位实体和组合动作。StarCraft II（星际争霸 II）中，智能体要同时理解小地图、资源、建筑、兵种、历史信息和对手状态，还要按顺序选择动作类型、延迟、队列、单位和目标位置。把所有信息压成一个固定向量、把所有动作当成一个巨大离散集合，都会迅速失去结构。</p><p>《蘑菇书》第十三章给出 AlphaStar 的输入、记忆和动作头拆解；Nature（自然）论文进一步展示了完整游戏、多智能体和人类对战评价。本篇只讲系统建模：状态如何分组、实体如何编码、记忆为何必要、动作如何自回归生成，以及这些设计对自动驾驶多模态规控有什么启发。论文成绩本身不等于方法在其他任务上自动成立。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-复杂环境首先是表示问题" tabindex="-1">1.1 复杂环境首先是表示问题 <a class="header-anchor" href="#_1-1-复杂环境首先是表示问题" aria-label="Permalink to &quot;1.1 复杂环境首先是表示问题&quot;">​</a></h3><p>状态由标量、实体、空间地图和历史组成，必须使用适合各自结构的编码器，不能简单拼接后期待网络自行恢复关系。</p><h3 id="_1-2-组合动作需要自回归结构" tabindex="-1">1.2 组合动作需要自回归结构 <a class="header-anchor" href="#_1-2-组合动作需要自回归结构" aria-label="Permalink to &quot;1.2 组合动作需要自回归结构&quot;">​</a></h3><p>动作类型、延迟、队列、选中单位和目标点存在条件依赖。前一个动作头的输出作为后一个动作头的输入，比一次性输出所有组合更可控。</p><h3 id="_1-3-记忆模块补充部分可观测信息" tabindex="-1">1.3 记忆模块补充部分可观测信息 <a class="header-anchor" href="#_1-3-记忆模块补充部分可观测信息" aria-label="Permalink to &quot;1.3 记忆模块补充部分可观测信息&quot;">​</a></h3><p>当前屏幕看不到全部地图和对手意图，LSTM（长短期记忆网络）等记忆模块把历史观测压缩进隐状态。</p><h3 id="_1-4-系统复杂度必须绑定评价协议" tabindex="-1">1.4 系统复杂度必须绑定评价协议 <a class="header-anchor" href="#_1-4-系统复杂度必须绑定评价协议" aria-label="Permalink to &quot;1.4 系统复杂度必须绑定评价协议&quot;">​</a></h3><p>输入限制、动作频率、视野范围、种族和对手池都会影响结果。只引用排名而不说明约束，无法复现结论。</p><p><img src="'+l+'" alt="AlphaStar 从多模态状态到组合动作的整体结构"></p><h2 id="二、alphastar-的状态为什么要分组" tabindex="-1">二、AlphaStar 的状态为什么要分组 <a class="header-anchor" href="#二、alphastar-的状态为什么要分组" aria-label="Permalink to &quot;二、AlphaStar 的状态为什么要分组&quot;">​</a></h2><h3 id="_2-1-标量数据描述全局上下文" tabindex="-1">2.1 标量数据描述全局上下文 <a class="header-anchor" href="#_2-1-标量数据描述全局上下文" aria-label="Permalink to &quot;2.1 标量数据描述全局上下文&quot;">​</a></h3><p>资源、人口、时间、科技等级和视野位置等信息适合用向量表示，通常交给 MLP（多层感知机）编码。</p><h3 id="_2-2-实体数据描述数量可变对象" tabindex="-1">2.2 实体数据描述数量可变对象 <a class="header-anchor" href="#_2-2-实体数据描述数量可变对象" aria-label="Permalink to &quot;2.2 实体数据描述数量可变对象&quot;">​</a></h3><p>建筑、单位和资源点拥有类型、位置、生命值、队伍、升级等属性。实体数量变化，编码器必须支持集合或序列输入。</p><h3 id="_2-3-地图数据保留空间关系" tabindex="-1">2.3 地图数据保留空间关系 <a class="header-anchor" href="#_2-3-地图数据保留空间关系" aria-label="Permalink to &quot;2.3 地图数据保留空间关系&quot;">​</a></h3><p>小地图和可见区域包含距离、障碍、地形与势力分布，适合使用卷积或空间编码器。</p><h3 id="_2-4-历史数据描述不可见状态" tabindex="-1">2.4 历史数据描述不可见状态 <a class="header-anchor" href="#_2-4-历史数据描述不可见状态" aria-label="Permalink to &quot;2.4 历史数据描述不可见状态&quot;">​</a></h3><p>敌方单位离开视野后仍可能存在，过去的资源变化和动作序列也会影响判断。记忆模块需要在时间维度融合信息。</p><p><img src="'+h+'" alt="AlphaStar 四类输入信息与对应编码器"></p><h2 id="三、实体编码器如何处理数量变化" tabindex="-1">三、实体编码器如何处理数量变化 <a class="header-anchor" href="#三、实体编码器如何处理数量变化" aria-label="Permalink to &quot;三、实体编码器如何处理数量变化&quot;">​</a></h2><h3 id="_3-1-每个实体先变成属性向量" tabindex="-1">3.1 每个实体先变成属性向量 <a class="header-anchor" href="#_3-1-每个实体先变成属性向量" aria-label="Permalink to &quot;3.1 每个实体先变成属性向量&quot;">​</a></h3><p>单位类型、位置、速度、生命、护盾和当前指令等属性经过嵌入和归一化，形成单个实体表示。</p><h3 id="_3-2-集合编码要减少顺序依赖" tabindex="-1">3.2 集合编码要减少顺序依赖 <a class="header-anchor" href="#_3-2-集合编码要减少顺序依赖" aria-label="Permalink to &quot;3.2 集合编码要减少顺序依赖&quot;">​</a></h3><p>同一批单位的排列顺序不应改变整体决策。注意力或池化机制可以聚合实体关系，但简单平均会丢掉关键个体信息。</p><h3 id="_3-3-注意力可以突出关键实体" tabindex="-1">3.3 注意力可以突出关键实体 <a class="header-anchor" href="#_3-3-注意力可以突出关键实体" aria-label="Permalink to &quot;3.3 注意力可以突出关键实体&quot;">​</a></h3><p>攻击目标、低血量单位、正在建造的建筑等实体可能比背景单位更重要。注意力权重提供一种关系建模方式，但不天然等于可解释因果。</p><h3 id="_3-4-实体编码还要保留空间位置" tabindex="-1">3.4 实体编码还要保留空间位置 <a class="header-anchor" href="#_3-4-实体编码还要保留空间位置" aria-label="Permalink to &quot;3.4 实体编码还要保留空间位置&quot;">​</a></h3><p>类型相同但位置不同的单位承担不同战术角色。位置、相对距离和地图坐标不能在嵌入中被完全抹平。</p><h2 id="四、地图编码器怎样保留空间结构" tabindex="-1">四、地图编码器怎样保留空间结构 <a class="header-anchor" href="#四、地图编码器怎样保留空间结构" aria-label="Permalink to &quot;四、地图编码器怎样保留空间结构&quot;">​</a></h2><h3 id="_4-1-小地图不是普通序列" tabindex="-1">4.1 小地图不是普通序列 <a class="header-anchor" href="#_4-1-小地图不是普通序列" aria-label="Permalink to &quot;4.1 小地图不是普通序列&quot;">​</a></h3><p>相邻格子的关系、障碍连通性和控制区域都具有局部结构。卷积或空间注意力比直接展平更适合提取这些模式。</p><h3 id="_4-2-局部特征需要与全局状态融合" tabindex="-1">4.2 局部特征需要与全局状态融合 <a class="header-anchor" href="#_4-2-局部特征需要与全局状态融合" aria-label="Permalink to &quot;4.2 局部特征需要与全局状态融合&quot;">​</a></h3><p>地图局部热点必须与资源、时间和对手信息联合解释。单独看局部图像无法决定长期策略。</p><h3 id="_4-3-多尺度地图对应不同决策" tabindex="-1">4.3 多尺度地图对应不同决策 <a class="header-anchor" href="#_4-3-多尺度地图对应不同决策" aria-label="Permalink to &quot;4.3 多尺度地图对应不同决策&quot;">​</a></h3><p>高层需要战略区域和基地关系，低层需要单位附近的局部目标。统一分辨率可能在两种需求之间折中失真。</p><h3 id="_4-4-可见地图不等于真实地图" tabindex="-1">4.4 可见地图不等于真实地图 <a class="header-anchor" href="#_4-4-可见地图不等于真实地图" aria-label="Permalink to &quot;4.4 可见地图不等于真实地图&quot;">​</a></h3><p>视野限制、遮挡和侦察动作决定了观测。模型必须在训练和评估中保持同样的信息边界。</p><h2 id="五、记忆模块为什么不可缺少" tabindex="-1">五、记忆模块为什么不可缺少 <a class="header-anchor" href="#五、记忆模块为什么不可缺少" aria-label="Permalink to &quot;五、记忆模块为什么不可缺少&quot;">​</a></h2><h3 id="_5-1-当前观测不是完整状态" tabindex="-1">5.1 当前观测不是完整状态 <a class="header-anchor" href="#_5-1-当前观测不是完整状态" aria-label="Permalink to &quot;5.1 当前观测不是完整状态&quot;">​</a></h3><p>对手曾经出现过但当前不可见的单位、过去的建造顺序和未确认信息都需要历史推断。</p><h3 id="_5-2-lstm-融合多模态嵌入" tabindex="-1">5.2 LSTM 融合多模态嵌入 <a class="header-anchor" href="#_5-2-lstm-融合多模态嵌入" aria-label="Permalink to &quot;5.2 LSTM 融合多模态嵌入&quot;">​</a></h3><p>标量、实体和地图编码后进入循环模块，隐状态保存一段时间内的摘要，再送入价值和动作头。</p><h3 id="_5-3-记忆长度影响探索与稳定性" tabindex="-1">5.3 记忆长度影响探索与稳定性 <a class="header-anchor" href="#_5-3-记忆长度影响探索与稳定性" aria-label="Permalink to &quot;5.3 记忆长度影响探索与稳定性&quot;">​</a></h3><p>记忆太短看不到战略线索，太长会增加优化难度和错误累积。截断反向传播、重置时机和隐藏状态初始化都要记录。</p><h3 id="_5-4-记忆不是事实存储器" tabindex="-1">5.4 记忆不是事实存储器 <a class="header-anchor" href="#_5-4-记忆不是事实存储器" aria-label="Permalink to &quot;5.4 记忆不是事实存储器&quot;">​</a></h3><p>隐状态是压缩表示，可能遗忘或混淆历史。需要用遮挡、重置和历史扰动实验检查它真正提供了什么。</p><p><img src="'+o+'" alt="多模态嵌入经过记忆模块再进入策略与价值头"></p><h2 id="六、组合动作为什么要分成多个动作头" tabindex="-1">六、组合动作为什么要分成多个动作头 <a class="header-anchor" href="#六、组合动作为什么要分成多个动作头" aria-label="Permalink to &quot;六、组合动作为什么要分成多个动作头&quot;">​</a></h2><h3 id="_6-1-动作类型决定后续参数" tabindex="-1">6.1 动作类型决定后续参数 <a class="header-anchor" href="#_6-1-动作类型决定后续参数" aria-label="Permalink to &quot;6.1 动作类型决定后续参数&quot;">​</a></h3><p>移动、攻击、建造和研究动作需要不同的延迟、目标单位或目标位置。先选类型可以减少无效组合。</p><h3 id="_6-2-动作参数按条件依次生成" tabindex="-1">6.2 动作参数按条件依次生成 <a class="header-anchor" href="#_6-2-动作参数按条件依次生成" aria-label="Permalink to &quot;6.2 动作参数按条件依次生成&quot;">​</a></h3><p>前一动作头的嵌入和共享隐状态输入下一个头，形成自回归动作序列。</p><h3 id="_6-3-组合概率可以按链式法则分解" tabindex="-1">6.3 组合概率可以按链式法则分解 <a class="header-anchor" href="#_6-3-组合概率可以按链式法则分解" aria-label="Permalink to &quot;6.3 组合概率可以按链式法则分解&quot;">​</a></h3><p>$$ \\pi(a|s)=\\pi(a_{type}|s)\\pi(a_{delay}|s,a_{type})\\cdots $$</p><p>每个头的概率共同决定完整动作的对数概率，策略梯度必须正确累加。</p><h3 id="_6-4-非法组合需要动作掩码" tabindex="-1">6.4 非法组合需要动作掩码 <a class="header-anchor" href="#_6-4-非法组合需要动作掩码" aria-label="Permalink to &quot;6.4 非法组合需要动作掩码&quot;">​</a></h3><p>没有目标单位的攻击、超出地图的目标点和资源不足的建造动作应在采样前屏蔽，不能只靠负奖励纠正。</p><p><img src="'+s+'" alt="AlphaStar 自回归动作头与动作掩码"></p><h2 id="七、alphastar-结构对自动驾驶有什么启发" tabindex="-1">七、AlphaStar 结构对自动驾驶有什么启发 <a class="header-anchor" href="#七、alphastar-结构对自动驾驶有什么启发" aria-label="Permalink to &quot;七、AlphaStar 结构对自动驾驶有什么启发&quot;">​</a></h2><h3 id="_7-1-多模态状态应按物理结构编码" tabindex="-1">7.1 多模态状态应按物理结构编码 <a class="header-anchor" href="#_7-1-多模态状态应按物理结构编码" aria-label="Permalink to &quot;7.1 多模态状态应按物理结构编码&quot;">​</a></h3><p>道路几何、车辆实体、交通灯、地图语义和历史轨迹不应全部压成无结构向量。</p><h3 id="_7-2-规划动作也有条件链" tabindex="-1">7.2 规划动作也有条件链 <a class="header-anchor" href="#_7-2-规划动作也有条件链" aria-label="Permalink to &quot;7.2 规划动作也有条件链&quot;">​</a></h3><p>驾驶意图、目标车道、速度曲线和轨迹控制存在层级关系，可使用条件动作头或分层接口减少非法组合。</p><h3 id="_7-3-记忆应服务于部分可观测推理" tabindex="-1">7.3 记忆应服务于部分可观测推理 <a class="header-anchor" href="#_7-3-记忆应服务于部分可观测推理" aria-label="Permalink to &quot;7.3 记忆应服务于部分可观测推理&quot;">​</a></h3><p>遮挡车辆、历史意图和感知延迟需要记忆，但记忆模块不能替代独立的跟踪、预测与安全监控。</p><p><img src="'+n+'" alt="自动驾驶多模态决策与独立安全层边界"></p><h2 id="八、一个最小实验怎样设计" tabindex="-1">八、一个最小实验怎样设计 <a class="header-anchor" href="#八、一个最小实验怎样设计" aria-label="Permalink to &quot;八、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_8-1-构造多模态导航任务" tabindex="-1">8.1 构造多模态导航任务 <a class="header-anchor" href="#_8-1-构造多模态导航任务" aria-label="Permalink to &quot;8.1 构造多模态导航任务&quot;">​</a></h3><p>同时提供局部图像、实体列表、全局标量和历史遮挡，比较单一向量编码与分组编码。</p><h3 id="_8-2-构造组合动作空间" tabindex="-1">8.2 构造组合动作空间 <a class="header-anchor" href="#_8-2-构造组合动作空间" aria-label="Permalink to &quot;8.2 构造组合动作空间&quot;">​</a></h3><p>先选择行为类型，再选择目标和参数，比较一次性动作头与自回归动作头的非法率和学习速度。</p><h3 id="_8-3-做记忆消融" tabindex="-1">8.3 做记忆消融 <a class="header-anchor" href="#_8-3-做记忆消融" aria-label="Permalink to &quot;8.3 做记忆消融&quot;">​</a></h3><p>比较无历史、短记忆和长记忆在遮挡、延迟和对手策略变化下的性能。</p><h3 id="_8-4-记录端到端开销" tabindex="-1">8.4 记录端到端开销 <a class="header-anchor" href="#_8-4-记录端到端开销" aria-label="Permalink to &quot;8.4 记录端到端开销&quot;">​</a></h3><p>报告实体数量、地图分辨率、记忆长度、动作头数量、推理延迟和显存，而不只报告成功率。</p><h2 id="九、最常见的实现错误" tabindex="-1">九、最常见的实现错误 <a class="header-anchor" href="#九、最常见的实现错误" aria-label="Permalink to &quot;九、最常见的实现错误&quot;">​</a></h2><h3 id="_9-1-随意打乱实体却不保留位置" tabindex="-1">9.1 随意打乱实体却不保留位置 <a class="header-anchor" href="#_9-1-随意打乱实体却不保留位置" aria-label="Permalink to &quot;9.1 随意打乱实体却不保留位置&quot;">​</a></h3><p>集合不变性不等于删除空间关系。实体编码必须兼顾排列鲁棒和位置语义。</p><h3 id="_9-2-训练时看到了评估不可用信息" tabindex="-1">9.2 训练时看到了评估不可用信息 <a class="header-anchor" href="#_9-2-训练时看到了评估不可用信息" aria-label="Permalink to &quot;9.2 训练时看到了评估不可用信息&quot;">​</a></h3><p>把全图、对手真实状态或未来动作输入训练，会让结果失去现实意义。</p><h3 id="_9-3-组合动作概率漏项" tabindex="-1">9.3 组合动作概率漏项 <a class="header-anchor" href="#_9-3-组合动作概率漏项" aria-label="Permalink to &quot;9.3 组合动作概率漏项&quot;">​</a></h3><p>只计算动作类型概率而忽略目标参数概率，会导致策略梯度与实际采样分布不一致。</p><h3 id="_9-4-用负奖励代替所有动作掩码" tabindex="-1">9.4 用负奖励代替所有动作掩码 <a class="header-anchor" href="#_9-4-用负奖励代替所有动作掩码" aria-label="Permalink to &quot;9.4 用负奖励代替所有动作掩码&quot;">​</a></h3><p>大量非法动作会浪费样本，也让策略在安全关键动作空间中承担不必要探索。</p><h2 id="十、学到什么程度才算掌握" tabindex="-1">十、学到什么程度才算掌握 <a class="header-anchor" href="#十、学到什么程度才算掌握" aria-label="Permalink to &quot;十、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_10-1-能按数据结构选择编码器" tabindex="-1">10.1 能按数据结构选择编码器 <a class="header-anchor" href="#_10-1-能按数据结构选择编码器" aria-label="Permalink to &quot;10.1 能按数据结构选择编码器&quot;">​</a></h3><p>你应能说明标量、实体、地图和历史分别适合什么表示。</p><h3 id="_10-2-能写出组合动作概率分解" tabindex="-1">10.2 能写出组合动作概率分解 <a class="header-anchor" href="#_10-2-能写出组合动作概率分解" aria-label="Permalink to &quot;10.2 能写出组合动作概率分解&quot;">​</a></h3><p>你应能正确处理条件动作头、对数概率累加和非法动作掩码。</p><h3 id="_10-3-能设计部分可观测消融" tabindex="-1">10.3 能设计部分可观测消融 <a class="header-anchor" href="#_10-3-能设计部分可观测消融" aria-label="Permalink to &quot;10.3 能设计部分可观测消融&quot;">​</a></h3><p>你应能通过遮挡和历史重置验证记忆模块是否真正提高了决策能力。</p><h3 id="_10-4-能进入-alphastar-训练机制" tabindex="-1">10.4 能进入 AlphaStar 训练机制 <a class="header-anchor" href="#_10-4-能进入-alphastar-训练机制" aria-label="Permalink to &quot;10.4 能进入 AlphaStar 训练机制&quot;">​</a></h3><p>下一篇将继续拆监督预训练、强化学习、V-trace（V 迹）、自博弈和联盟训练。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter13/chapter13.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十三章 AlphaStar 论文解读</a></p><p><a href="https://www.nature.com/articles/s41586-019-1724-z" target="_blank" rel="noreferrer">Vinyals 等《Grandmaster level in StarCraft II using multi-agent reinforcement learning》</a></p><p><a href="https://deepmind.google/blog/alphastar-grandmaster-level-in-starcraft-ii-using-multi-agent-reinforcement-learning/" target="_blank" rel="noreferrer">DeepMind AlphaStar 项目介绍</a></p>',101)])])}const k=e(p,[["render",d]]);export{f as __pageData,k as default};
